inline const char* fhUiText(const char* text) {
  if (!text || !fhUiLanguage) return text;
  for (const auto& entry : fhUiEntries) if (std::string_view(text) == entry.key)
    return entry.translations[fhUiLanguage - 1];
  return text;
}
inline std::string fhUiLabel(const char* text) { return std::string(fhUiText(text)) + "###" + text; }
